import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserOpenURL } from '../wailsjs/runtime/runtime';
import './style.css';
import {manifestItems, planItems, planMetric, planRoot, planStops, routeNodes} from './marketPlan';
import {applyJobResults, applyJobState, isRealMarketPlan, latestRevisionResults, loadMarketWorkspace, saveMarketWorkspace} from './marketWorkspace';

const PLACEHOLDER='https://relay.example.invalid';
const OFFICIAL=(import.meta.env.VITE_ALICE_OFFICIAL_SERVER||PLACEHOLDER).trim().replace(/\/$/,'');
type View='overview'|'character'|'economy'|'activity'|'market'|'intel'|'alerts'|'agent'|'settings';
type Snapshot={CharacterID:number;Domain:string;Payload:any;FetchedAt:string;ExpiresAt:string;Stale:boolean;Source:string};
type MarketOrder={duration:number;is_buy_order:boolean;issued:string;location_id:number;order_id:number;price:number;system_id:number;type_id:number;volume_remain:number;volume_total:number};
type MarketHistory={average:number;highest:number;lowest:number;date:string;order_count:number;volume:number};
type Finding={kind:string;value:string;stance:string;summary:string;confidence:number;observedAt:string};
type SyncJob={Kind:string;Status:string;RunAfter:string;Attempts:number;LastErrorCode?:string};
type RegionStatus={regionId?:number;state?:string;startedAt?:string;endedAt?:string;error?:string;schedule?:Record<string,any>;job?:Record<string,any>;snapshot?:Record<string,any>;[key:string]:any};
type Api={
 StartupError?:()=>Promise<string>;RelayURL?:()=>Promise<string>;SetRelayURL?:(v:string)=>Promise<void>;CheckRelayHealth?:()=>Promise<void>;PairingState?:()=>Promise<any>;BeginOAuthLogin?:(n:string)=>Promise<any>;PollOAuthLogin?:()=>Promise<any>;ClearPairing?:()=>Promise<void>;
 FetchEVEContractItems?:(characterID:number,contractID:number)=>Promise<any[]>;FetchEVEContractBids?:(characterID:number,contractID:number)=>Promise<any[]>;FetchEVEMailBody?:(characterID:number,mailID:number)=>Promise<any>;FetchEVEKillmailDetail?:(characterID:number,killmailID:number,hash:string)=>Promise<any>;FetchEVESyncStatus?:()=>Promise<SyncJob[]>;FetchEVEUniverseNames?:(ids:number[])=>Promise<{id:number;name:string;category:string}[]>;FetchEVEAccountCharacters?:()=>Promise<Snapshot[]>;FetchEVECharacterSnapshots?:(id:number)=>Promise<Snapshot[]>;FetchEVEStatus?:()=>Promise<any>;FetchEVECharacterTradeContext?:(id:number,max:number,reserve:number)=>Promise<any>;FetchEVETradeRoute?:(from:number,to:number,mode:string,min:number)=>Promise<any>;FetchEVESecureTradeRoute?:(from:number,to:number,min:number,max:number)=>Promise<any>;FetchEVESecureTradeRoutes?:(queries:any[])=>Promise<any[]>;FetchEVETradeHubs?:()=>Promise<any[]>;FetchEVEHubComparison?:(id:number)=>Promise<any[]>;FetchEVETradePlans?:(req:any)=>Promise<any[]>;CreateEVEMarketPlanJob?:(req:any)=>Promise<any>;FetchEVEMarketPlanJob?:(id:string)=>Promise<any>;FetchEVEMarketPlanResults?:(id:string,after:number)=>Promise<any>;CancelEVEMarketPlanJob?:(id:string)=>Promise<any>;CollectEVETradeRegion?:(regionID:number)=>Promise<RegionStatus>;FetchEVETradeRegionCollection?:(regionID:number)=>Promise<RegionStatus>;SearchEVETradeCandidates?:(req:any)=>Promise<any>;ComposeEVETradePlan?:(req:any)=>Promise<any[]>;ChainEVETradePlans?:(req:any)=>Promise<any[]>;FetchEVEMarketPrices?:()=>Promise<any[]>;FetchEVEUniverseType?:(id:number)=>Promise<any>;FetchEVEUniverseSystem?:(id:number)=>Promise<any>;FetchEVECorporation?:(id:number)=>Promise<any>;FetchEVEAlliance?:(id:number)=>Promise<any>;FetchEVEUniverseStation?:(id:number)=>Promise<any>;FetchEVEMarketOrders?:(r:number,o:string,t:number)=>Promise<MarketOrder[]>;FetchEVEMarketHistory?:(r:number,t:number)=>Promise<MarketHistory[]>;
 ChatLogStatus?:()=>Promise<any>;GameLogStatus?:()=>Promise<any>;RecentChatIntel?:()=>Promise<any[]>;RecentGameEvents?:()=>Promise<any[]>;ParseIntel?:(t:string)=>Promise<Finding[]>;PublishChatIntel?:(id:string)=>Promise<void>;
 FetchAlerts?:(c:number,l:number)=>Promise<any>;FetchConversations?:()=>Promise<any[]>;SDEStatus?:()=>Promise<any>;SDETypeNames?:(ids:number[])=>Promise<Record<number,string>>;SDELocationNames?:(ids:number[])=>Promise<Record<number,string>>;SDERegions?:()=>Promise<{id:string;name:string;kind:string}[]>;SDERegionForSystem?:(id:number)=>Promise<number>;
};
const api=()=>((window as any).go?.main?.App||{}) as Api;
const fmt=(v?:string)=>v?new Date(v).toLocaleString():'—';
const num=(v:any,d=2)=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:d});
function Icon({name}:{name:string}){const paths:Record<string,string>={overview:'M3 3h7v7H3zM14 3h7v4h-7zM14 11h7v10h-7zM3 14h7v7H3z',character:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm-7 9a7 7 0 0 1 14 0',economy:'M4 19V9m5 10V5m6 14v-7m5 7V3',market:'M3 17l5-5 4 4 8-9M15 7h5v5',intel:'M12 3l8 4v5c0 5-3.5 8-8 9-4.5-1-8-4-8-9V7z',alerts:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',agent:'M8 9h8M9 13h.01M15 13h.01M5 6h14v12H5zM12 3v3',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7zM19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.12 2.12-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1 1.55V21h-3v-.79a1.7 1.7 0 0 0-1-1.55 1.7 1.7 0 0 0-1.88.34l-.06.06-2.12-2.12.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.55-1H3v-3h.05A1.7 1.7 0 0 0 4.6 10a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.12-2.12.06.06A1.7 1.7 0 0 0 8.26 6.3a1.7 1.7 0 0 0 1-1.55V4h3v.75a1.7 1.7 0 0 0 1 1.55 1.7 1.7 0 0 0 1.88-.34l.06-.06 2.12 2.12-.06.06A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.55 1H21v3h-.05a1.7 1.7 0 0 0-1.55 1z'};return <svg viewBox="0 0 24 24"><path d={paths[name]} /></svg>}
function Fresh({s}:{s?:Snapshot}){if(!s)return <span className="tag muted">无数据</span>;return <span className={`tag ${s.Stale?'warn':'ok'}`}>{s.Stale?'已过期':'新鲜'} · {fmt(s.FetchedAt)}</span>}
function App(){
 const A=api();const [view,setView]=useState<View>('overview');const [connected,setConnected]=useState(false);const [paired,setPaired]=useState('');const [characterID,setCharacterID]=useState(()=>Number(localStorage.getItem('alice.character.id')||0));const [snapshots,setSnapshots]=useState<Snapshot[]>([]);const [syncJobs,setSyncJobs]=useState<SyncJob[]>([]);const [accountCharacters,setAccountCharacters]=useState<Snapshot[]>([]);const [resolved,setResolved]=useState<Record<string,any>>({});const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [serverStatus,setServerStatus]=useState<any>();const [chat,setChat]=useState<any>({});const [game,setGame]=useState<any>({});const [chatEvents,setChatEvents]=useState<any[]>([]);const [gameEvents,setGameEvents]=useState<any[]>([]);const [alerts,setAlerts]=useState<any[]>([]);const [sde,setSde]=useState<any>({});const [oauth,setOauth]=useState(false);
 const [intel,setIntel]=useState('');const [findings,setFindings]=useState<Finding[]>([]);const [globalTypeNames,setGlobalTypeNames]=useState<Record<number,string>>({});const [marketWorkspace,setMarketWorkspace]=useState(loadMarketWorkspace);useEffect(()=>saveMarketWorkspace(marketWorkspace),[marketWorkspace]);
 const byDomain=useMemo(()=>Object.fromEntries(snapshots.map(s=>[s.Domain,s])),[snapshots]);const payload=(d:string)=>byDomain[d]?.Payload||{};
 const refreshBase=useCallback(async()=>{setLoading(true);setError('');try{await A.CheckRelayHealth?.();setConnected(true)}catch{setConnected(false)}const rs=await Promise.allSettled([A.FetchEVEStatus?.(),A.ChatLogStatus?.(),A.GameLogStatus?.(),A.RecentChatIntel?.(),A.RecentGameEvents?.(),A.FetchAlerts?.(0,30),A.SDEStatus?.(),A.PairingState?.(),A.FetchEVESyncStatus?.()]);if(rs[0].status==='fulfilled')setServerStatus(rs[0].value);if(rs[1].status==='fulfilled')setChat(rs[1].value||{});if(rs[2].status==='fulfilled')setGame(rs[2].value||{});if(rs[3].status==='fulfilled')setChatEvents(rs[3].value||[]);if(rs[4].status==='fulfilled')setGameEvents(rs[4].value||[]);if(rs[5].status==='fulfilled')setAlerts((rs[5].value as any)?.items||(rs[5].value as any)?.Items||[]);if(rs[6].status==='fulfilled')setSde(rs[6].value||{});if(rs[7].status==='fulfilled')setPaired((rs[7].value as any)?.DeviceID||'');if(rs[8].status==='fulfilled')setSyncJobs((rs[8].value as SyncJob[])||[]);setLoading(false)},[A]);
 const loadCharacter=useCallback(async()=>{if(!characterID||!A.FetchEVECharacterSnapshots)return;setLoading(true);try{const data=await A.FetchEVECharacterSnapshots(characterID);setSnapshots(data||[]);setAccountCharacters(prev=>prev.length?prev:data||[]);localStorage.setItem('alice.character.id',String(characterID))}catch(e:any){setSnapshots([]);if(A.FetchEVEAccountCharacters){try{const all=await A.FetchEVEAccountCharacters();const id=all?.[0]?.CharacterID;if(id&&id!==characterID){setCharacterID(id);setSnapshots(all.filter(s=>s.CharacterID===id));localStorage.setItem('alice.character.id',String(id));return}}catch{/* use the original character error */}}setError(e?.message||'角色快照不可用；请确认已重新授权且同步已完成。')}finally{setLoading(false)}},[A,characterID]);

 useEffect(()=>{void (async()=>{try{const current=(await A.RelayURL?.())?.trim();if(!current&&OFFICIAL!==PLACEHOLDER)await A.SetRelayURL?.(OFFICIAL)}catch(e:any){setError(`初始化 Relay 地址失败：${e?.message||String(e)}`);return}const startupError=await A.StartupError?.();if(startupError)setError(startupError);await refreshBase();if(!A.FetchEVEAccountCharacters)return;try{const all=await A.FetchEVEAccountCharacters();if(all?.length){setAccountCharacters(all);const available=[...new Set(all.map(s=>s.CharacterID).filter(id=>id>0))];const id=available.includes(characterID)?characterID:available[0];if(id){setCharacterID(id);setSnapshots(all.filter(s=>s.CharacterID===id));localStorage.setItem('alice.character.id',String(id))}}}catch{/* private data may not be authorized yet */}})()},[]);useEffect(()=>{if(characterID)void loadCharacter()},[characterID]);useEffect(()=>{void (async()=>{const loc=payload('location'),ship=payload('ship');const next:Record<string,any>={};const tasks:Promise<void>[]=[];if(loc.solar_system_id&&A.FetchEVEUniverseSystem)tasks.push(A.FetchEVEUniverseSystem(loc.solar_system_id).then(v=>{next.system=v}).catch(()=>{}));if(ship.ship_type_id&&A.FetchEVEUniverseType)tasks.push(A.FetchEVEUniverseType(ship.ship_type_id).then(v=>{next.shipType=v}).catch(()=>{}));const identity=payload('identity');if(identity.corporation_id&&A.FetchEVECorporation)tasks.push(A.FetchEVECorporation(identity.corporation_id).then(v=>{next.corporation=v}).catch(()=>{}));if(identity.alliance_id&&A.FetchEVEAlliance)tasks.push(A.FetchEVEAlliance(identity.alliance_id).then(v=>{next.alliance=v}).catch(()=>{}));if(loc.station_id&&A.FetchEVEUniverseStation)tasks.push(A.FetchEVEUniverseStation(loc.station_id).then(v=>{next.station=v}).catch(()=>{}));await Promise.all(tasks);setResolved(next)})()},[snapshots]);useEffect(()=>{const ids=new Set<number>();for(const s of snapshots){const p=s.Payload;if(Array.isArray(p))for(const x of p)if(Number(x?.type_id)>0)ids.add(Number(x.type_id))}for(const m of ['single','portfolio','chain'])for(const p of marketWorkspace.byMode[m].plans){const r=planRoot(p);for(const x of [r,...planItems(p)]){const id=Number(x?.typeId??x?.TypeID??x?.type_id??0);if(id>0)ids.add(id)}}if(ids.size)A.SDETypeNames?.([...ids]).then(v=>setGlobalTypeNames(n=>({...n,...(v||{})}))).catch(()=>{})},[snapshots,marketWorkspace,A]);useEffect(()=>{const timer=setInterval(()=>void refreshBase(),30000);return()=>clearInterval(timer)},[refreshBase]);
 const beginOAuth=async()=>{try{setOauth(true);setError('');const start=await A.BeginOAuthLogin?.('Alice-EVE Desktop');if(!start?.authorizationUrl)throw new Error('服务端未返回授权地址');BrowserOpenURL(start.authorizationUrl);const until=Date.now()+600000;const timer=setInterval(async()=>{if(Date.now()>until){clearInterval(timer);setOauth(false);setError('浏览器授权等待超时，请重新授权。');return}try{const r=await A.PollOAuthLogin?.();if(r&&!r.pending){clearInterval(timer);setOauth(false);setPaired(r.deviceId||'authorized');setError('');void refreshBase();try{const all=await A.FetchEVEAccountCharacters?.();if(all?.length){setAccountCharacters(all);const id=all.some((s:any)=>s.CharacterID===characterID)?characterID:all[0].CharacterID;setCharacterID(id);setSnapshots(all.filter((s:any)=>s.CharacterID===id));localStorage.setItem('alice.character.id',String(id))}}catch(e:any){setError(`Alice 登录已完成，但角色数据暂不可用：${e?.message||String(e)}。请稍后点击“刷新角色”。`)}}}catch(e:any){clearInterval(timer);setOauth(false);setError(`授权回调失败：${e?.message||String(e)||'未知错误'}。请重新授权。`)}},2000)}catch(e:any){setOauth(false);setError(`无法启动 EVE SSO 授权：${e?.message||String(e)||'未知错误'}`)}};
 const nav:Array<[View,string,string]>= [['overview','overview','总览'],['character','character','角色'],['economy','economy','经济'],['activity','alerts','活动'],['market','market','市场'],['intel','intel','情报'],['alerts','alerts','告警'],['agent','agent','Agent'],['settings','settings','设置']];
 const title=nav.find(n=>n[0]===view)?.[2]||'';
 return <div className="app-shell"><aside className="sidebar"><div className="brand"><b>AE</b><span>ALICE-EVE<small>DATA CONSOLE</small></span></div><nav>{nav.map(([v,i,l])=><button className={view===v?'active':''} onClick={()=>setView(v)} key={v}><Icon name={i}/><span>{l}</span>{v==='alerts'&&alerts.length>0&&<em>{alerts.length}</em>}</button>)}</nav><div className="node"><span><i className={connected?'ok':''}/>{connected?'ALICE ONLINE':'ALICE OFFLINE'}</span><code>v0.1 · {paired?'AUTHORIZED':'NO DEVICE'}</code></div></aside><main className="console"><header className="toolbar"><div><h1>{title}</h1><span className="crumb">ALICE-EVE / {view.toUpperCase()}</span></div><div className="tools"><span className="health"><i className={chat.running?'ok':''}/>LOGS</span><span className="health"><i className={serverStatus?'ok':''}/>ESI</span><button onClick={()=>void refreshBase()} disabled={loading}>刷新</button></div></header>{error&&<div className="errorbar">{error}{/authentication required|401|unauthori/i.test(error)&&<button onClick={()=>void beginOAuth()} disabled={oauth}>{oauth?'等待浏览器授权…':'重新授权'}</button>}<button onClick={()=>setError('')}>关闭</button></div>}
 <section className="workspace">
 {view==='overview'&&<><div className="kpis"><KPI label="EVE 在线" value={serverStatus?num(serverStatus.players,0):'—'} sub={serverStatus?.server_version||'等待公共 ESI'}/><KPI label="Chat Intel" value={num(chat.findings,0)} sub={chat.running?'监听中':'未启动'}/><KPI label="Combat Events" value={num(game.events,0)} sub={game.running?'监听中':'未启动'}/><KPI label="SDE Entities" value={num(sde.entries,0)} sub={sde.ready?'索引就绪':'未配置'}/></div><div className="two-pane"><Panel title="数据源状态"><StatusTable rows={[['Relay',connected?'已连接':'断开',connected],['EVE Public ESI',serverStatus?'正常':'不可用',!!serverStatus],['Chatlogs',chat.running?'监听中':'未启动',!!chat.running],['Gamelogs',game.running?'监听中':'未启动',!!game.running],['SDE',sde.ready?'就绪':'未配置',!!sde.ready]]}/></Panel><Panel title="角色同步"><div className="auth-box"><p>{paired?'Alice 设备已授权。角色由当前账户自动发现，不能手工输入。':'需要通过 EVE SSO 授权以启用角色数据同步。'}</p><label>已授权角色<select value={characterID||''} onChange={e=>setCharacterID(Number(e.target.value))}>{[...new Map(accountCharacters.filter(s=>s.Domain==='identity').map(s=>[s.CharacterID,s])).values()].map(s=><option key={s.CharacterID} value={s.CharacterID}>{s.Payload?.name||`角色 ${s.CharacterID}`} · {s.CharacterID}</option>)}</select></label><div className="row"><button className="primary" onClick={beginOAuth} disabled={oauth}>{oauth?'等待浏览器授权…':'重新授权 EVE SSO'}</button><button onClick={()=>void loadCharacter()} disabled={!characterID}>读取快照</button></div><small>{snapshots.length} 个领域快照 · Access token 不会进入桌面端</small></div></Panel></div></>}
 {view==='character'&&<Character domains={byDomain} characters={accountCharacters} characterID={characterID} setCharacterID={setCharacterID} resolved={resolved} reload={loadCharacter}/>}
 <PageSlot active={view==='economy'}><Economy domains={byDomain} A={A} characterID={characterID} prefetchedNames={globalTypeNames}/></PageSlot>
 <PageSlot active={view==='activity'}><Activity domains={byDomain} A={A} characterID={characterID}/></PageSlot>
 <PageSlot active={view==='market'}><TradeMonitor A={A} characterID={characterID} resolved={resolved} workspace={marketWorkspace} setWorkspace={setMarketWorkspace} prefetchedNames={globalTypeNames}/></PageSlot>
 {view==='intel'&&<Intel chat={chat} game={game} chats={chatEvents} games={gameEvents} intel={intel} setIntel={setIntel} findings={findings} parse={async()=>setFindings(await A.ParseIntel?.(intel)||[])}/>}
 {view==='alerts'&&<Panel title={`告警 (${alerts.length})`}><DataTable heads={['类型','标题','摘要','级别','时间']} rows={alerts.map(x=>[x.type||x.Type,x.title||x.Title,x.summary||x.Summary,x.severity||x.Severity,fmt(x.createdAt||x.CreatedAt)])}/></Panel>}
 {view==='agent'&&<Empty title="Agent Proxy" text="Agent 是只读辅助入口。角色、经济和市场查询优先使用结构化数据面板。"/>}
 {view==='settings'&&<Settings A={A} beginOAuth={beginOAuth} oauth={oauth} paired={paired} syncJobs={syncJobs}/>}
 </section><footer className="statusbar"><span><i className={connected?'ok':''}/>Relay {connected?'Connected':'Offline'}</span><span><i className={serverStatus?'ok':''}/>ESI {serverStatus?'Online':'Unknown'}</span><span>Privacy mode active</span><span className="push">SDE {sde.ready?`${sde.entries} entities`:'not configured'}</span></footer></main></div>}
function PageSlot({active,children}:{active:boolean;children:React.ReactNode}){return <div className="page-slot" hidden={!active} aria-hidden={!active}>{children}</div>}
function KPI({label,value,sub}:{label:string,value:any,sub:string}){return <div className="kpi"><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>}
function Panel({title,actions,children}:{title:string,actions?:React.ReactNode,children:React.ReactNode}){return <div className="panel"><div className="panel-head"><b>{title}</b>{actions}</div><div className="panel-body">{children}</div></div>}
function StatusTable({rows}:{rows:[string,string,boolean][]}){return <div className="status-table">{rows.map(r=><div key={r[0]}><span>{r[0]}</span><b className={r[2]?'good':'dim'}><i/>{r[1]}</b></div>)}</div>}
function DataTable({heads,rows}:{heads:string[],rows:any[][]}){return <div className="table-scroll"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{React.isValidElement(c)?c:String(c??'—')}</td>)}</tr>):<tr><td colSpan={heads.length} className="no-data">暂无数据</td></tr>}</tbody></table></div>}
function Character({domains,characters,characterID,setCharacterID,resolved,reload}:{domains:Record<string,Snapshot>;characters:Snapshot[];characterID:number;setCharacterID:(n:number)=>void;resolved:Record<string,any>;reload:()=>void}){const id=domains.identity?.Payload||{},online=domains.online?.Payload||{},loc=domains.location?.Payload||{},ship=domains.ship?.Payload||{},skills=domains.skills?.Payload||{},queue=domains.skillqueue?.Payload||[];const choices=[...new Map(characters.filter(s=>s.Domain==='identity').map(s=>[s.CharacterID,s])).values()];const shipName=String(ship.ship_name||'').replace(/^u'|'$/g,'').replace(/\\u([0-9a-fA-F]{4})/g,(_,h)=>String.fromCharCode(parseInt(h,16)));return <><div className="actionbar"><label>已授权角色<select value={characterID||''} onChange={e=>setCharacterID(Number(e.target.value))}>{choices.map(s=><option key={s.CharacterID} value={s.CharacterID}>{s.Payload?.name||`角色 ${s.CharacterID}`} · {s.CharacterID}</option>)}</select></label><button className="primary" onClick={reload}>刷新角色</button><Fresh s={domains.identity}/></div><div className="kpis"><KPI label="角色" value={id.name||'—'} sub={online.online?`在线 · 登录 ${online.logins||0} 次`:`离线 · ${fmt(online.last_logout)}`}/><KPI label="位置" value={resolved.system?.name||'等待解析'} sub={`安全等级 ${resolved.system?.security_status?.toFixed?.(2)??'—'}`}/><KPI label="当前舰船" value={resolved.shipType?.name||'等待解析'} sub={shipName||'未命名舰船'}/><KPI label="技能点" value={domains.skills?num(skills.total_sp,0):'未授权'} sub={domains.skills?`${skills.skills?.length||0} 项技能`:'需要 Skills scope'}/></div><div className="two-pane wide-left"><Panel title="技能队列" actions={<Fresh s={domains.skillqueue}/>}><DataTable heads={['技能','等级','开始','完成']} rows={(queue||[]).map((q:any)=>[q.skill_name||`Type ${q.skill_id}`,q.finished_level,fmt(q.start_date),fmt(q.finish_date)])}/>{!domains.skillqueue&&<div className="scope-note">需要技能队列授权后才能显示技能名称、等级与剩余时间。</div>}</Panel><Panel title="角色详情" actions={<Fresh s={domains.identity}/>}><dl className="inspector"><dt>角色名称</dt><dd>{id.name||'—'}</dd><dt>角色 ID</dt><dd>{characterID||'—'}</dd><dt>军团</dt><dd>{resolved.corporation?.name||`ID ${id.corporation_id||'—'}`}</dd><dt>联盟</dt><dd>{resolved.alliance?.name||(id.alliance_id?`ID ${id.alliance_id}`:'无联盟')}</dd><dt>安全状态</dt><dd>{id.security_status??'—'}</dd><dt>太阳系</dt><dd>{resolved.system?.name||`ID ${loc.solar_system_id||'—'}`}</dd><dt>空间站</dt><dd>{resolved.station?.name||(loc.station_id?`ID ${loc.station_id}`:'太空中')}</dd><dt>最后登录</dt><dd>{fmt(online.last_login)}</dd><dt>最后登出</dt><dd>{fmt(online.last_logout)}</dd><dt>舰船类型</dt><dd>{resolved.shipType?.name||`Type ${ship.ship_type_id||'—'}`}</dd><dt>数据源</dt><dd>{domains.identity?.Source||'—'}</dd></dl></Panel></div></>}
function MissingDomain({domain,scope}:{domain:string;scope:string}){return <div className="scope-note"><b>{domain} 尚未同步</b><span>需要 {scope}；完成授权后由服务端自动同步。空数据与数值 0 会被明确区分。</span></div>}
